  Stage_129501_Name = {
    Text = "Le jeu commence"
  },
  Stage_129502_Desc = {
    Text = "Ne t'arrête pas, ne recule pas. \n Si les personnes bienveillantes lâchent leur arme, alors le mal en profitera pour poursuivre."
