  Stage_139577_Name = {
    Text = "Ruée vers l'or noir"
  },
  Stage_139578_Desc = {
    Text = "Les poches pleines de Cœur d'argent et de Billet Rose Dorée, le général victorieux rentre chez lui chargé de butin."
  },
  Stage_139578_Name = {
    Text = "Revenir avec un chargement complet"
  },
  Stage_139579_Desc = {
    Text = "Vous avez jeté votre dévolu sur le plus gros chat de tous. Et lui a jeté son dévolu sur vous."
