  Stage_139581_Name = {
    Text = "Premier seau d'argent"
  },
  Stage_139582_Desc = {
    Text = "Les chats noirs ripostent — ça veut dire que vous faites quelque chose de bien."
  },
  Stage_139582_Name = {
    Text = "Résistance à l'arrestation"
  },
  Stage_139583_Desc = {
    Text = "Plus grand filet, plus de chats — et les gros ont besoin d'un grand filet. Ramenez-les tous !"
  },
  Stage_139583_Name = {
    Text = "Ramenez-les tous !"
  },
  Stage_140299_Desc = {
    Text = "Éclore, et danser.\nVous avez décidé que, peu importe les périls du chemin à venir, vous ne lâcherez jamais sa main.\nÀ l'instant où nous nous séparons, que le monde inversé se remplisse de «réel»."
  },
  Stage_140299_Name = {Text = "Au revoir"},
