  Stage_145322_Name = {
    Text = "Couronne du Désir· cinq"
  },
  Stage_145323_Desc = {
    Text = "Prosternez-vous. Inclinez la tête.\n\nC'est la seule posture convenable pour des fourmis face à un dieu."
  },
  Stage_145323_Name = {
    Text = "Première section"
  },
  Stage_145324_Desc = {
    Text = "Rien ne se trouve derrière elle ; aucune fin ne se trouve devant elle. Et elle s'en réjouit."
  },
  Stage_145324_Name = {
    Text = "La cinquième section"
  },
  Stage_145325_Desc = {
    Text = "Vous vous tenez devant le miroir et voyez celui que vous aimez le plus. Un parent, un enfant, un ami cher, ou peut-être vous-même...\nL'amour. Léviathan méprise ce mot. L'âme de l'Exécuteur ne tolère aucun fardeau.\nLevez votre lame, et tuez-les.\nÀ partir de ce moment, vous n'aurez plus aucune faiblesse.\nÀ partir de ce moment, vous n'aurez plus aucun chemin de retour."
  },
