  Stage_146928_Desc = {
    Text = "Une princesse en détresse sauvée par un chevalier, c'est une histoire traditionnelle connue de tous."
  },
  Stage_146928_Name = {Text = "Princesse"},
  Stage_146929_Desc = {
    Text = "Le dragon s'éveille, la haine s'embrase à nouveau. Le souffle de la bête jaillit des rochers, le venin de la guerre brûle avec ardeur, sans s'éteindre à ce jour.\nLa terre gronde comme le tonnerre."
  },
  Stage_146929_Name = {
    Text = "Repaire du Dragon"
  },
  Stage_146930_Desc = {
    Text = "Le chevalier s'engagea sur des chemins inconnus, traversant des plaines et des collines désolées, avec pour seule compagnie son ombre.\nPeut-être était-il déjà mort, mais sans témoin, on finit par l'oublier.\nLe monde est si silencieux."
  },
  Stage_146930_Name = {Text = "Tombeau"},
  Stage_146931_Desc = {
    Text = "Quarante jours et quarante nuits de pluie s'abattirent sur la terre, nous ne pouvons continuer, et pourtant nous continuerons."
  },
  Stage_146931_Name = {Text = "Île Pomme"},
  Stage_146932_Desc = {
    Text = "Le dragon s'éveille, la haine s'embrase à nouveau. Le souffle de la bête jaillit des rochers, le venin de la guerre brûle avec ardeur, sans s'éteindre à ce jour.\nLa terre gronde comme le tonnerre."
  },
  Stage_146932_Name = {
    Text = "Repaire du Dragon"
  },
  Stage_146933_Desc = {
    Text = "C'est la racine et la fleur du jardin céleste, la couronne de tous les désirs du monde, une abondance intarissable.\nBois le vin dans ta coupe, et tu verras ce que tu désires le plus ardemment."
  },
  Stage_146933_Name = {Text = "Calice"},
  Stage_146934_Desc = {
    Text = "Le dragon s'éveille, la haine s'embrase à nouveau. Le souffle de la bête jaillit des rochers, le venin de la guerre brûle avec ardeur, sans s'éteindre à ce jour.\nLa terre gronde comme le tonnerre."
  },
  Stage_146934_Name = {
    Text = "Repaire du Dragon"
  },
