  Stage_20089_Desc = {
    Text = "Elle a tenu sa promesse, et maintenant vous pouvez enfin rentrer chez vous ensemble."
  },
  Stage_20089_Name = {
    Text = "Tête dorée"
  },
  Stage_20090_Desc = {
    Text = "Le Salon est l'événement artistique le plus important de la Cité. \nIci, les inconnus cherchent le succès, et les réussis cherchent l'éternité."
  },
  Stage_20090_Name = {
    Text = "Décès de Mme Coral"
  },
  Stage_20091_Desc = {
    Text = "La réponse se trouve au centre de la mer."
  },
  Stage_20091_Name = {
    Text = "Milieu de mer"
  },
  Stage_20092_Desc = {
    Text = "Ernst Claudel était autrefois le seigneur de Besançon.\nMême aujourd'hui, cette famille reste très estimée dans la région."
  },
  Stage_20092_Name = {
    Text = "Étreinte épistolaire"
  },
  Stage_20426_Desc = {
    Text = "La fin est inévitable. Peu importe à quel point vous essayez ou à quel point elle lutte, le passé ne peut être changé."
  },
  Stage_20426_Name = {
    Text = "Fin resplendissante"
  },
  Stage_20427_Desc = {
    Text = "Les rêves ne sont pas toujours doux, tout comme de belles mélodies ne jouent pas pour toujours."
  },
  Stage_20427_Name = {
    Text = "Rideau final"
  },
  Stage_20428_Desc = {
    Text = "Le roi est emprisonné sur son trône élevé.\nLe monde change, pourtant sa tristesse reste inchangée."
  },
  Stage_20428_Name = {
    Text = "Son Royaume"
  },
  Stage_20429_Desc = {
    Text = "Elle erre sans but à travers des fragments de souvenirs.\nInconsciente, insensible, répétant indéfiniment..."
  },
  Stage_20429_Name = {
    Text = "Barrière de mémoire"
  },
  Stage_20430_Desc = {
    Text = "Que se cache-t-il au bout du labyrinthe ? La lumière du jour, la nuit ou une illusion sans fin ?\nElle doit trouver la réponse elle-même."
  },
  Stage_20430_Name = {
    Text = "La fin du labyrinthe"
  },
  Stage_20431_Desc = {
    Text = [[
Des rejetons, encore des rejetons, un flot incessant de rejetons...
Ils sont ses seuls amants.]]
  },
  Stage_20431_Name = {
    Text = "Esprit–ruche"
  },
  Stage_20432_Desc = {
    Text = "N'ouvre jamais une porte qui ne t'appartient pas..."
  },
  Stage_20432_Name = {Text = "Porte"},
  Stage_20433_Desc = {
    Text = "Les rêves ne sont pas toujours doux, tout comme de belles mélodies ne jouent pas pour toujours."
  },
  Stage_20433_Name = {
    Text = "Rideau final"
  },
  Stage_20434_Desc = {
    Text = "Ernst Claudel était autrefois le seigneur de Besançon.\nMême aujourd'hui, cette famille reste très estimée dans la région."
  },
  Stage_20434_Name = {
    Text = "Étreinte épistolaire"
  },
  Stage_20435_Desc = {
    Text = "Il a fait tout ce qu'il pouvait. Maintenant, laissons le temps tisser une nouvelle ballade."
  },
  Stage_20435_Name = {
    Text = "Nouvelle ballade"
  },
  Stage_20436_Desc = {
    Text = "Un souvenir chéri ou un rêve inoubliable ?"
  },
  Stage_20436_Name = {
    Text = "Fils du passé"
  },
  Stage_20437_Desc = {
    Text = [[
Des rejetons, encore des rejetons, un flot incessant de rejetons...
Ils sont ses seuls amants.]]
  },
  Stage_20437_Name = {
    Text = "Esprit–ruche"
  },
  Stage_20438_Desc = {
    Text = "Les rêves ne sont pas toujours doux, tout comme de belles mélodies ne jouent pas pour toujours."
  },
  Stage_20438_Name = {
    Text = "Rideau final"
  },
  Stage_20439_Desc = {
    Text = "C'est un secret entre vous, gravé dans vos âmes et porté à travers l'éternité."
  },
  Stage_20439_Name = {
    Text = "Rêve ou idéal"
  },
  Stage_20440_Desc = {
    Text = "Le monde après l'explosion est sombre. Vous erretez dans le monde des esprits, incertain de ce qui vous attend vous et Erica."
  },
  Stage_20440_Name = {
    Text = "Ainsi parla la voix"
  },
  Stage_20441_Desc = {
    Text = "Un autre rêve, un autre passé—cette fois, tu vois Erica avec un corps de chair et de sang."
  },
  Stage_20441_Name = {
    Text = "Commencer le test"
  },
  Stage_20442_Desc = {
    Text = "Le monde après l'explosion est sombre. Vous erretez dans le monde des esprits, incertain de ce qui vous attend vous et Erica."
  },
  Stage_20442_Name = {
    Text = "Ainsi parla la voix"
  },
  Stage_20443_Desc = {
    Text = "Le monde après l'explosion est sombre. Vous erretez dans le monde des esprits, incertain de ce qui vous attend vous et Erica."
  },
  Stage_20443_Name = {
    Text = "Ainsi parla la voix"
  },
  Stage_20444_Desc = {
    Text = "Ernst Claudel était autrefois le seigneur de Besançon.\nMême aujourd'hui, cette famille reste très estimée dans la région."
  },
  Stage_20444_Name = {
