  Stage_24183_Name = {
    Text = "Niveau d'épreuve de la Dame Rouge"
  },
  Stage_24184_Name = {
    Text = "Niveau de démonstration de la Fleur de Boue"
  },
  Stage_24423_Desc = {
    Text = "Aucun citoyen de Londinium ne refuserait un thé chaud fraîchement préparé.\nMême si c'est une tasse de thé oolong de lamproie."
  },
  Stage_24423_Name = {
    Text = "Élixir de lamproie"
  },
  Stage_24424_Desc = {
    Text = "Tout le monde choisi par le destin croit qu'il est l'exception.\nLe destin se moque de la probabilité."
  },
  Stage_24424_Name = {
    Text = "Prisonnier du Destin"
  },
  Stage_24425_Desc = {
    Text = "Coupe. \nElle jura de rompre tous les liens avec sa vie précédente.\nTout comme couper un ruban en deux avec des ciseaux."
  },
  Stage_24425_Name = {Text = "Pour Sorel"},
  Stage_24426_Desc = {
    Text = "Une fois de plus, tu deviens un captif de la sympathie, plongeant profondément dans son âme."
  },
  Stage_24426_Name = {
    Text = "Verdict déchu"
  },
  Stage_24427_Desc = {
    Text = "Au début de l'Histoire, vous serez témoin d'une mort magnifique.\nBien que ce soit le début, ce n'est pas du tout la fin."
  },
  Stage_24427_Name = {
    Text = "Chanson de boisson"
  },
  Stage_24428_Desc = {
    Text = "Le nom de la fille est Sorel, la fierté du village.\nObéissante et propre, elle a une apparence blanc neige et marche avec de petits pas, comme une véritable dame.\nMais contrairement à ces dames, elle ne rêve jamais."
  },
  Stage_24429_Desc = {
    Text = "La logique est comme du whisky : trop en perd l'avantage."
  },
  Stage_24429_Name = {
    Text = "Harmonie Masquée"
  },
  Stage_24430_Desc = {
    Text = "Sous son soin méticuleux, le cancer de l'ambition a finalement prospéré comme des roses en pleine floraison."
  },
  Stage_24430_Name = {
    Text = "Festivités écarlates"
  },
  Stage_24431_Desc = {
    Text = "Slurp. Slurp.\nNous nous tortillons dans l'ombre, nous chuchotons des secrets.\nDes corps gras laissent des traces de larmes sinueuses sous la lumière de la lune—salées, tu sais."
  },
  Stage_24431_Name = {Text = "Œuf"},
  Stage_24432_Desc = {
    Text = [[
Scones, macarons, et chocolat chaud fumant...
Le souhait de la femme de chambre est simple : manger mieux, et encore plus.]]
  },
  Stage_24432_Name = {
    Text = "Vœu de la Femme de Chambre"
  },
  Stage_24433_Desc = {
    Text = "Prenez garde, prenez garde. \nLa dame que vous admirez tous n'est pas une véritable dame. \nMais qui s'en soucie ?"
  },
  Stage_24433_Name = {
    Text = "Guide de la Dame"
  },
  Stage_24434_Desc = {
    Text = "La rose incline sa tête fine aux carillons, tandis que le vautour se perd parmi les fleurs fétides.\nPersonne ne chante, personne ne parle. Le monde s'efface avec son passage."
  },
  Stage_24434_Name = {
    Text = "Funérailles de Rose"
  },
  Stage_24435_Desc = {
    Text = "Elle vide les sources, tuant des oiseaux innocents.\nElle amène des vents dorés, balayant les champs comme des météores.\nElle embrase le monde avec le Désir, puis le réduit en cendres."
  },
  Stage_24435_Name = {
    Text = "Dame au camélia"
  },
  Stage_24439_Desc = {
    Text = "Prenez garde, prenez garde. \nLa dame que vous admirez tous n'est pas une véritable dame. \nMais qui s'en soucie ?"
  },
