  Stage_35099_Desc = {
    Text = "\"Chut... devine ce que j'ai vu à travers tes yeux ?\" \nAprès qu'Aurita ait été effrayée aux larmes par le Gardien, Lotan a presque détruit le quatrième mur de la chambre du Gardien parce que les pleurs d'Aurita étaient juste trop troublants."
  },
  Stage_35099_Name = {
    Text = "IX·Quatrième mur du théâtre"
  },
  Stage_35100_Desc = {
    Text = "\"Ne laissez pas le public s'immerger entièrement dans l'intrigue ; faites-les analyser et critiquer ce qui se passe sur scène.\"\nEn ce qui concerne cette théorie, Aurita a commenté : Aurita ne veut pas être réprimandée par qui que ce soit ! Aurita veut juste être de bons amis avec tout le monde !"
  },
  Stage_35100_Name = {
    Text = "VIII·Effet de distanciation"
  },
  Stage_35129_Desc = {
    Text = "Elle est la frontière où les rêves et la réalité s'entrelacent, le reflet au fond de chaque âme qui regarde le ciel nocturne."
  },
  Stage_35129_Name = {
    Text = "Étoiles tordues"
  },
  Stage_35129_StageInitStateText = {
    Text = "Cauchemar Marin"
  },
  Stage_35130_Desc = {
    Text = "Elle est prête."
  },
  Stage_35130_Name = {
    Text = "Flamme intériorisée"
  },
  Stage_35571_Desc = {
    Text = "Parce que vous êtes l'ami d'Aurita, elle veut vous présenter à tous ses amis."
  },
  Stage_35571_Name = {
    Text = "Répertoire d'amis"
  },
  Stage_35572_Desc = {
    Text = "Parce que vous êtes l'ami d'Aurita, elle veut vous présenter à tous ses amis."
  },
  Stage_35572_Name = {
    Text = "Répertoire d'amis"
  },
  Stage_35573_Desc = {
    Text = "Parce que vous êtes l'ami d'Aurita, elle veut vous présenter à tous ses amis."
  },
  Stage_35573_Name = {
    Text = "Répertoire d'amis"
  },
  Stage_35574_Desc = {
    Text = "Aurita t'aime et veut que tu deviennes un ami qui peut la rejoindre lors d'une journée ordinaire."
  },
  Stage_35574_Name = {
    Text = "Jour Silencieux"
  },
  Stage_35575_Desc = {
    Text = "Avec tout le monde aux côtés d'Aurita, Aurita n'a pas du tout peur de s'endormir."
  },
  Stage_35575_Name = {
    Text = "Palais aquatique"
  },
  Stage_35843_Name = {
    Text = "Niveau d'essai de la Dame Aequor"
  },
  Stage_35857_Desc = {
    Text = "Les étoiles sont allées là où elles appartiennent, communiquant de manières incompréhensibles aux humains, tissant une toile invisible qui capture le flux du temps et la lumière des années passées."
  },
  Stage_35857_Name = {
    Text = "Chemin astral inconnu"
  },
