  Stage_46546_Name = {
    Text = "Mémoire Inconsciente : Émergence II"
  },
  Stage_46547_Desc = {
    Text = "Je ne sais pas quand elle est devenue la juge ici.\nElle a jugé une personne dont le nom était caché et l'a condamnée à mort.\nPuis elle a entendu la révélation : \"Vous êtes cette personne.\"\nOui, tous les prisonniers, juges et prêtres ici ont le même visage"
  },
  Stage_46547_Name = {
    Text = "Amygdale · Émergence IV"
  },
  Stage_46548_Desc = {
    Text = "L’Enfer est une pièce vide remplie d'innombrables miroirs.\nElle n'ose pas ouvrir les yeux, car tout ce qu'elle voit est son visage pâle et terrifié.\nUne voix résonne dans le vide :\nCeci est une rétribution. Dans la vie, tu n'avais qu'une seule coquille ; dans la mort, tu fais face à d'innombrables."
  },
  Stage_46548_Name = {
    Text = "Miroir · Émergence VI"
  },
  Stage_46549_Desc = {
    Text = "Je ne sais pas quand elle est devenue la juge ici.\nElle a jugé une personne dont le nom était caché et l'a condamnée à mort.\nPuis elle a entendu la révélation : \"Vous êtes cette personne.\"\nOui, tous les prisonniers, juges et prêtres ici ont le même visage"
  },
