  Stage_56404_Desc = {
    Text = "Murphy apprit qu'elle n'était pas la première Sainte ; au cours de milliers d'années, les cœurs de nombreuses filles ont résonné d'un battement similaire.\nDans d'innombrables temps et espaces, d'innombrables cœurs se superposent et palpitent."
  },
  Stage_56404_Name = {
    Text = "Rift Temporel·Folie"
  },
  Stage_56404_StageInitStateText = {
    Text = "Cauchemar Marin"
  },
  Stage_56405_Desc = {
    Text = "C'est le dernier repos digne pour toute Vie.\nAvec Aequor comme cercueil et les cieux et la terre comme lit, Dieu repose dans les courants océaniques."
  },
  Stage_56405_Name = {
    Text = "Voile·Folie"
  },
  Stage_56405_StageInitStateText = {
    Text = "Cauchemar Marin"
  },
  Stage_56407_Desc = {
    Text = "Il est descendu silencieusement et sans émotion.\nSon cœur bat à travers son sang, continuant à vivre sans désir."
  },
  Stage_56407_Name = {
    Text = "Son Arrivée · Folie"
  },
  Stage_56407_StageInitStateText = {
    Text = "Cauchemar Marin"
  },
  Stage_56408_Desc = {
    Text = "Elle compte les étoiles dans le ciel, attendant un moment qu'elle n'anticipe pas. \n\"Quand les étoiles s'alignent,\" au moment où les étoiles émergent au-dessus de la mer, elle se transformera en l'une d'elles."
  },
  Stage_56408_Name = {
    Text = "Étoile jaune · Folie"
  },
  Stage_56408_StageInitStateText = {
    Text = "Cauchemar Marin"
  },
  Stage_56409_Desc = {
    Text = "Elle n'avait pas le droit de décider du sort de l'embryon implémenté dans sa poitrine.\nElle n'avait pas le droit de décider où fuir, quelle main tenir, ou avec qui errer.\nFace au destin errant au milieu des illusions de la mer, tout le monde n'était qu'un agneau attendant l'abattage."
  },
  Stage_56409_Name = {
    Text = "Agneau sacrificiel·Folie"
  },
  Stage_56409_StageInitStateText = {
    Text = "Cauchemar Marin"
  },
  Stage_56410_Desc = {
