  Stage_58378_Name = {
    Text = "Révélation · Quatre"
  },
  Stage_58379_Desc = {
    Text = "Isarau a disparu, comme s'il n'avait jamais existé.\nToutes les rues et les gens n'étaient que des illusions. Ils étaient nés de ses rêves, prenant forme jour après jour, et puis :\n\"Bang—\"\nLe rêve s'est terminé. Elle n'a jamais ouvert les yeux pour voir Isarau, tout comme elle n'a jamais ouvert les yeux pour se voir elle-même."
  },
