  Stage_58385_Name = {
    Text = "Mirage·Folie"
  },
  Stage_58385_StageInitStateText = {Text = "Finale"},
  Stage_58386_Desc = {
    Text = "Elle ferme les yeux et flotte sans but dans le vide de l'univers. \nUne année, cent ans... Enfin, un jour, elle se dit : \"Tout va bien. Laissez-moi définir la vérité et le mensonge.\"\nLa reine et sa ville immortelle—Isalaw, ainsi restent suspendues au milieu de la vaste galaxie de l'univers. \nElle partage l'histoire d'Isalaw avec moi afin qu'elle soit éternellement rappelée."
  },
