  Stage_58428_Desc = {
    Text = "La prière était la première chose que les Lémuriens ont apprise, mais ce qui est apparu devant elle pour la protéger n'était jamais son roi."
  },
  Stage_58428_Name = {
    Text = "Doute·Quatre"
  },
  Stage_58429_Desc = {
