  },
  Stage_59056_Name = {Text = "Destin"},
  Stage_59057_Desc = {
    Text = "Des airs de danse enjoués, des plaisanteries agréables et une monotonie fade.\nOui, reposez-vous durant le troisième mouvement. C'est sûr, calme et sans événement."
  },
  Stage_59057_Name = {
    Text = "Troisième mouvement"
  },
  Stage_59058_Desc = {
