  Stage_66016_Desc = {
    Text = "Il est la volonté suprême, la Relique de l'univers, celui qui met fin à toutes choses. \nGémis devant Lui. Pour ton courage faible, pour Son autorité sans bornes."
  },
  Stage_66016_Name = {
