  Stage_66381_Desc = {
    Text = "Ne vous inquiétez pas, la peur est le plus primal instinct des êtres vivants.  \nLe dieu ne trouble jamais une fourmi. Il vous bénit avec le réveil"
  },
  Stage_66381_Name = {
    Text = "Musée de Cire·La Vision de la Peur"
  },
  Stage_66381_StageInitStateText = {Text = "Primordial"},
  Stage_66382_Desc = {
    Text = "Chante, grande Relique ! \nQuand Il rêve, le peuple prospère.  \nQuand Il ouvre les yeux, toutes choses deviennent poussière."
  },
  Stage_66382_Name = {
    Text = "Brilpert : La Vision de l'Hérésie"
  },
  Stage_66382_StageInitStateText = {Text = "Primordial"},
  Stage_66383_Desc = {
    Text = "Ressentez la douleur, ressentez le cadeau le plus primitif de la volonté suprême. \nDans la douleur, entrez un aperçu de la majesté du Créateur"
  },
  Stage_66383_Name = {
    Text = "Rai : Le Regard Pénétrant"
  },
  Stage_66383_StageInitStateText = {Text = "Primordial"},
  Stage_66384_Desc = {
    Text = "Ne luttez pas. Ne résistez pas. Ne tentez pas de comprendre l'incompréhensible.  \nDans le regard de la volonté suprême, accueillez la fin du rêve"
  },
  Stage_66384_Name = {
