  Stage_70410_Name = {
    Text = "Préférence du chat · Partie 2"
  },
  Stage_70411_Desc = {
    Text = "Les oreilles de chat tournent, les griffes de chat fleurissent et la queue se dresse.\nDans votre chacha avec le chat, sa joie déborde"
  },
  Stage_70411_Name = {
    Text = "Joie du chat · Partie 1"
  },
  Stage_70412_Desc = {
    Text = "Les pattes du chat continuent de fouiller devant vous, s'étendant et se rétractant, s'étendant et se rétractant.\nLes empreintes de pattes noires comme la nuit sont imprimées sur vos chaussures d'uniforme scolaire.\nVous ne pouvez vous empêcher de lever votre poing aussi gros qu'un pot de sable."
  },
  Stage_70412_Name = {
    Text = "Empreinte de griffes du chat · Partie 1"
  },
  Stage_70413_Desc = {
    Text = "Le chat noir familier possédait manifestement des souvenirs de vous, inclinant son chapeau en salutation. \nUn gant blanc, qui semblait surgir de nulle part, fut jeté à vos pieds ; ce n'était pas une salutation, mais une invitation à un duel de gentlemen"
  },
  Stage_70413_Name = {
    Text = "<Yellow:Salutations du chat · Partie 1>"
  },
  Stage_70414_Desc = {
    Text = "Le chat noir familier possédait manifestement des souvenirs de vous, inclinant son chapeau en salutation. \nUn gant blanc, qui semblait surgir de nulle part, fut jeté à vos pieds ; ce n'était pas une salutation, mais une invitation à un duel de gentlemen"
  },
  Stage_70414_Name = {
    Text = "Salutations du chat · Partie 3"
  },
  Stage_70415_Desc = {
    Text = "Le chat noir familier possédait manifestement des souvenirs de vous, inclinant son chapeau en salutation. \nUn gant blanc, qui semblait surgir de nulle part, fut jeté à vos pieds ; ce n'était pas une salutation, mais une invitation à un duel de gentlemen"
  },
  Stage_70415_Name = {
    Text = "Salutations du chat · Partie 2"
  },
  Stage_70416_Desc = {
    Text = "Quelle nuit délicieuse, tout incite le chat à s'attarder et à être inoubliable !  \nLaissez la lumière brillante de la lune percer la fenêtre fleurie, illuminant le festin joyeux !  \nOh, louez les chats !"
  },
  Stage_70416_Name = {
    Text = "Fête du chat · Partie 2"
  },
  Stage_70417_Desc = {
    Text = "Les oreilles de chat tournent, les griffes de chat fleurissent et la queue se dresse.\nDans votre chacha avec le chat, sa joie déborde"
  },
  Stage_70417_Name = {
    Text = "Joie du chat · Partie 2"
  },
  Stage_70418_Desc = {
    Text = "Les pattes du chat continuent de fouiller devant vous, s'étendant et se rétractant, s'étendant et se rétractant.\nLes empreintes de pattes noires comme la nuit sont imprimées sur vos chaussures d'uniforme scolaire.\nVous ne pouvez vous empêcher de lever votre poing aussi gros qu'un pot de sable."
  },
  Stage_70418_Name = {
    Text = "Empreinte de griffes du chat · Partie 3"
  },
  Stage_70419_Desc = {
