    Text = "Cadavres, l'odeur du sang, une tête qui a disparu.\nVa-t-elle vous protéger ? Ou prendra-t-elle plutôt votre vie ?"
  },
  Stage_75770_Name = {
    Text = "Cadavre sans tête·Folie"
  },
  Stage_75770_StageInitStateText = {Text = "Finale"},
