  Stage_7635_Desc = {
    Text = "Ils sont comme des sorciers insaisissables, dérivant dans les fissures du temps et de l'espace.\nPas de haine, pas de peur, pas de pitié."
  },
  Stage_7635_Name = {
    Text = "Après-image dimensionnelle II"
  },
  Stage_7636_Desc = {
    Text = "Elle porte la relique sainte, guide les fidèles avec la doctrine, et répand la foi avec des crocs venimeux."
  },
  Stage_7636_Name = {
    Text = "Prise dévouée III"
  },
  Stage_7637_Desc = {
    Text = "Ils existaient bien avant la naissance des étoiles.\nIls sont à la fois Illusion et tout."
  },
  Stage_7637_Name = {
    Text = "Image Résiduelle Trouble V"
  },
  Stage_7638_Desc = {
    Text = "Ils gardent silencieusement les secrets de l'océan, avec des âmes aussi profondes que le cosmos."
  },
  Stage_7638_Name = {
    Text = "Spectre Abyssal V"
  },
  Stage_76399_Desc = {
