  Stage_7673_Name = {
    Text = "Plongée Fantasmagorique I"
  },
  Stage_7674_Desc = {
    Text = "L'idole s'effondrant observe son peuple;\nElle les voit survivre, procréer, s'entretuer... puis enfin, l'oublier.\nL'idole effondrée se languit de son peuple..."
  },
  Stage_7674_Name = {
    Text = "Plongée Fantasmagorique III"
  },
  Stage_7675_Desc = {
    Text = "Scarborough, une ville côtière dans le Yorkshire du Nord, présente des falaises imposantes et des baies dorées, en faisant une destination de vacances élégante et charmante."
  },
  Stage_7675_Name = {
    Text = "Été de Scarborough"
  },
  Stage_7676_Desc = {
    Text = "L'idole s'effondrant observe son peuple;\nElle les voit survivre, procréer, s'entretuer... puis enfin, l'oublier.\nL'idole effondrée se languit de son peuple..."
  },
  Stage_7676_Name = {
    Text = "Plongée Fantasmagorique I"
  },
  Stage_7677_Desc = {
    Text = "Une petite souris, une petite souris.\nCours, cours, elle a coupé sa queue avec un couteau de chef."
  },
  Stage_7677_Name = {
    Text = "Brown, en avant !"
  },
  Stage_7678_Desc = {
    Text = "L'idole s'effondrant observe son peuple;\nElle les voit survivre, procréer, s'entretuer... puis enfin, l'oublier.\nL'idole effondrée se languit de son peuple..."
  },
  Stage_7678_Name = {
    Text = "Plongée Fantasmagorique VII"
  },
  Stage_7679_Desc = {
    Text = "L'idole s'effondrant observe son peuple;\nElle les voit survivre, procréer, s'entretuer... puis enfin, l'oublier.\nL'idole effondrée se languit de son peuple..."
  },
  Stage_7679_Name = {
    Text = "Plongée Fantasmagorique VI"
  },
  Stage_7680_Desc = {
    Text = "Oh, bras, ces bras agaçants ! Ils ne cessent de tirer mes cheveux."
  },
  Stage_7680_Name = {
    Text = "Vingt-quatre"
  },
  Stage_7681_Desc = {
    Text = "Plouf, c'est fissuré.\nPlouf, c'est cassé."
  },
  Stage_7681_Name = {
    Text = "Maison de poupée"
  },
  Stage_7682_Desc = {
    Text = "Bien sûr, mon bébé. Pleure autant que tu le veux, et mets ta douleur en valeur comme une œuvre d'art."
  },
  Stage_7682_Name = {
    Text = "Fille et larmes"
  },
  Stage_7683_Desc = {
    Text = "Bien sûr, bien sûr. Les yeux sont la prison de l'esprit, et l'âme est le lien qui enchaîne le corps."
  },
  Stage_7683_Name = {
    Text = "Mélancolie anatomique"
  },
  Stage_7684_Desc = {
    Text = "Doux, riche et adoré par les enfants.\nÉlégant, sublime et désiré par les adultes."
  },
  Stage_7684_Name = {Text = "Art sucré"},
  Stage_76854_Desc = {
    Text = "Ce désastre invisible renaît, engloutissant tout ce qui est et ce qui a été de ce monde dans les profondeurs des abysses."
  },
  Stage_76854_Name = {
    Text = "Zone de Désastre: Vague 1: Alerte de niveau IV"
  },
  Stage_76855_Desc = {
    Text = "L'ancienne Calamité s'éveille, traverse les frontières jusqu'à entrer dans notre monde et enflamme l'infinie mer de corruption."
  },
  Stage_76855_Name = {
    Text = "Zone de Désastre: Vague 5: Alerte de niveau III"
