    Text = "Les interactions avec la Dame Jonquille sont toujours transactionnelles. La Dame Jonquille apparaît et propose un marché, mais les mystérieux attaquants accepteront-ils cette transaction ?"
  },
  Stage_7913_Name = {
    Text = "Échange équitable"
  },
  Stage_7914_Desc = {
    Text = "Dans le métro, vous avez été attaqué par des assassins mystérieux..."
  },
  Stage_7914_Name = {
    Text = "Les sans amis"
  },
  Stage_7915_Desc = {
    Text = "Suivant les rumeurs sur le chien de l'enfer \"Cerberus\", les Enquêteurs de Mythag arrivent aux abords d'une petite ville appelée Rye près de Londinium, explorant les secrets des disparitions..."
  },
  Stage_7915_Name = {
    Text = "Penser avant d'agir"
  },
  Stage_7916_Desc = {
    Text = "Le ton de la folie et l'odeur forte, c'est l'accueil de Rai."
  },
  Stage_7916_Name = {
    Text = "Bienvenue à seigle"
  },
  Stage_7917_Desc = {
    Text = "Bonne nouvelle et mauvaise nouvelle. Les indices perdus ne réapparaîtront pas, mais de nouvelles affaires se préparent dans l'ombre. Croyez-moi, les enquêteurs ne repartiront pas les mains vides cette fois."
  },
  Stage_7917_Name = {
    Text = "Bonne nouvelle, mauvaise nouvelle"
  },
  Stage_7918_Desc = {
    Text = "Ici se trouvent les ruines d'une ancienne ville.\nElle sommeille tout comme son maître."
  },
  Stage_7918_Name = {
    Text = "Ruines de Ponape IV"
  },
  Stage_7919_Desc = {
    Text = "Elworth est situé au pôle de Kadath, recouvert de glace et de neige perpétuelles.\nSous la coque épaisse et dure de glace, le léger pouls de la vie peut être vaguement détecté."
  },
  Stage_7919_Name = {
    Text = "Sommets Chaotiques III"
  },
  Stage_7920_Desc = {
    Text = "Ici repose une université, marquée et brisée, épuisée de toute sa force\n Son courage offrait autrefois une pâle lueur d'espoir quant à la survie de l'humanité\n Et voyez devant vous... ce qu'elle est devenue."
  },
  Stage_7920_Name = {
    Text = "Plongée Fantasmagorique VII"
  },
  Stage_7921_Desc = {
    Text = "Ils se tordent et fusionnent dans l'obscurité, puis sont soigneusement rangés dans les idoles.\nC'est une réunion tant attendue."
  },
  Stage_7921_Name = {
    Text = "Marais de Caro : Fissure I"
  },
  Stage_7922_Desc = {
    Text = "Offrez la réalité forgée à partir de Caro, un Abysse insatiable."
  },
  Stage_7922_Name = {
    Text = "Image après Mort Organique IV"
  },
  Stage_7923_Desc = {
    Text = "Le musée de cire Rogers est situé profondément sur Southwark Street, près d'un affluent de la Tamise.\nIl est discret, mais attire de nombreux amateurs d'art avant-gardiste."
  },
  Stage_7923_Name = {
    Text = "Musée de Cire Fou IV"
  },
