  Stage_8069_Name = {
    Text = "Plongée Fantasmagorique VI"
  },
  Stage_8070_Desc = {
    Text = "Ils se tordent et fusionnent dans l'obscurité, puis sont soigneusement rangés dans les idoles.\nC'est une réunion tant attendue."
  },
  Stage_8070_Name = {
    Text = "Relique Aequor·Fissure VI"
  },
  Stage_8071_Desc = {
    Text = "Ils étaient à l'origine un mélange inconscient de tristesse, de déformation et de naïveté,\nmais étaient déguisés en enfants joyeux, adultes et animaux de compagnie.\nN'ayant jamais goûté au bonheur, ils sont devenus les pires acteurs."
  },
  Stage_8071_Name = {
    Text = "Secret de la Sculpture en Cire III"
  },
  Stage_8072_Desc = {
    Text = "Il chasse sans relâche ceux qui enfreignent les règles.  \nQuant à ce qui constitue des \"règles\", et ce qui constitue \"une infraction\" ?  \nLe chien de chasse ne pense jamais—cela ne ferait que freiner sa vitesse d'attaque."
  },
  Stage_8072_Name = {
    Text = "Ombre au-delà de moi"
  },
  Stage_8073_Desc = {
    Text = "Ils sont comme des sorciers insaisissables, dérivant dans les fissures du temps et de l'espace.\nPas de haine, pas de peur, pas de pitié."
  },
  Stage_8073_Name = {
    Text = "Après-image dimensionnelle V"
  },
  Stage_8074_Desc = {
    Text = "\nSe tortillant et s'écoulant... Le renflement primordial glisse hors des fissures des entraves.\nC'est le prix qu'elle paie pour \"la liberté\"."
  },
  Stage_8074_Name = {
    Text = "Chaîne d'Obscurité I"
  },
