  Stage_88916_Name = {
    Text = "Liberté et mort · I"
  },
  Stage_88917_Desc = {
    Text = "Il a toujours eu deux ombres ; maintenant il a perdu une. \nIl marche seul sous le ciel nocturne silencieux, chantant la chanson qu'il a composée durant son enfance. \nOiseaux, oiseaux, où êtes-vous... \nOmbres, ombres, rentrez vite..."
  },
  Stage_88917_Name = {
    Text = "Voyage solitaire · Partie 4"
  },
