  Stage_88923_Name = {
    Text = "Ignorants · Partie 3"
  },
  Stage_88924_Desc = {
    Text = "La composition du désert est : chaleur brûlante, sécheresse, vent et poussière, dunes de sable infinies, reptiles agiles, cactus, et une beauté à la peau comme du miel."
  },
  Stage_88924_Name = {
    Text = "Sable et miel"
  },
  Stage_88925_Desc = {
    Text = "Je tiens le feu que tu as une fois allumé. \nTu m'as autrefois guidé, je serai tes yeux, te menant à voir la lumière à nouveau.\nLe chemin que tu as parcouru, je vais avancer pour toi, toutes les clôtures rouillées s'effondreront devant ce feu."
  },
