  Stage_98829_Name = {
    Text = "Éveil du silence · troisième"
  },
  Stage_98830_Desc = {
    Text = "Selon la légende, le destin des jumeaux est de s'entrelacer tout au long de leur vie, indissociables. \n Sous ce ciel étoilé qui a donné naissance à d'innombrables vies, nous nous retrouverons finalement."
  },
  Stage_98830_Name = {
